    <style>
        .cc{max-width:1240px;margin:auto;color:#24364b}.cc .cc-header{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:24px}.cc h3{font-size:24px;font-weight:700;margin:4px 0 8px}.cc .cc-eyebrow{color:#536c8b;font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase}.cc .cc-muted{color:#788798;font-size:13px}.cc .cc-badge{background:#eaf4f0;color:#32745b;border-radius:20px;padding:8px 14px;font-size:12px;white-space:nowrap}.cc .cc-panel{background:#fff;border:1px solid #e3e9ef;border-radius:14px;padding:24px;margin-bottom:20px;box-shadow:0 4px 18px #203b5510}.cc .cc-panel h5{font-size:16px;font-weight:700;margin-bottom:5px}.cc .cc-label{font-size:13px;font-weight:600;margin-bottom:8px;display:block}.cc .form-control{border:1px solid #d9e2eb;border-radius:8px;padding:11px 13px;font-size:14px;background:#fff;color:#24364b;min-height:44px}.cc .form-control:focus{border-color:#4a80ba;box-shadow:0 0 0 3px #4a80ba18}.cc textarea.form-control{line-height:1.6;resize:vertical}.cc .cc-block{margin-top:22px}.cc .cc-step{display:inline-flex;align-items:center;justify-content:center;background:#edf3fa;color:#3b6696;width:29px;height:29px;border-radius:8px;margin-right:9px;font-size:13px}.cc .cc-code{background:#f5f8fb;border-radius:10px;padding:14px;margin:18px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:8px;text-align:center}.cc .cc-code small{display:block;font-size:10px;color:#748499;text-transform:uppercase;margin-bottom:5px}.cc .cc-code strong{font-size:16px;font-variant-numeric:tabular-nums}.cc .cc-name{white-space:pre-line;font-weight:600;font-size:13px;line-height:1.7}.cc .cc-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.cc .cc-stat{border-top:1px solid #e6ecf2;padding-top:13px}.cc .cc-stat small{display:block;color:#7a8797;font-size:11px;margin-bottom:4px}.cc .cc-stat strong{font-size:18px}.cc .cc-photo{width:100%;height:130px;object-fit:contain;background:#f6f8fa;border:1px solid #e8edf2;border-radius:8px}.cc .cc-empty{height:90px;display:flex;align-items:center;justify-content:center;background:#fff7e7;border-radius:8px;font-size:12px;color:#8b692c;text-align:center;padding:12px}.cc .cc-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid #e9eef3;padding-top:22px;margin-top:24px}.cc .cc-submit{background:#245f97;color:white;border:0;border-radius:9px;font-weight:600;padding:13px 22px;font-size:14px}.cc .cc-submit:hover{background:#194d7d}.cc .cc-submit:disabled{opacity:.65}.cc .cc-fixed{font-size:12px;line-height:1.7;color:#778698}.cc .text-danger{font-size:12px;margin-top:5px}.cc .cc-panel summary{font-size:12px;color:#55708c;cursor:pointer}.cc .cc-description{font-size:13px;line-height:1.6;color:#6b7c91;margin:0}@media(max-width:767px){.cc .cc-header,.cc .cc-footer{align-items:flex-start;flex-direction:column}.cc .cc-panel{padding:18px}.cc .cc-submit{width:100%}.cc h3{font-size:21px}}
